from pathlib import Path

HTML = r'''<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Inventário Digital | REBIO ASP</title>
<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><link rel="stylesheet" href="{{ url_for('static',filename='style.css') }}"><script defer src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script defer src="{{ url_for('static',filename='app.js') }}"></script></head><body>
<a class="skip" href="#main">Pular para o conteúdo</a><main id="main">
<section id="login-panel" class="login-layout"><div class="login-brand"><div><h1>REBIO<br>Alto da Serra de Paranapiacaba</h1><p>Sistema interno de inventário digital georreferenciado e monitoramento de trilhas ecológicas e nascentes hídricas.</p></div></div><div class="login-form-panel"><form id="login-form"><h2>Bem-vindo</h2><label for="username">Login</label><input id="username" name="username" placeholder="Digite seu login" autocomplete="username" required><label for="password">Senha</label><input id="password" type="password" placeholder="••••••••" autocomplete="current-password" required><p id="login-error" role="alert"></p><button id="login-button" type="submit">Entrar</button></form></div></section>
<section id="workspace" hidden><header class="app-header"><a class="brand" href="/" aria-label="REBIO ASP, início"><span class="brand-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="m8 3-5 8h3l-4 6h12l-4-6h3L8 3Zm8 1-4 7h2l-3 6h11l-4-6h2l-4-7ZM8 17v4m8-4v4"/></svg></span>REBIO ASP</a><span class="app-title">Inventário Digital</span><div id="identity"></div></header>
<div class="inventory-layout"><aside id="sidebar" aria-label="Registros do inventário">
<section id="list-panel" class="side-panel"><div class="panel-heading"><h1>Registros</h1><button id="new-feature">+ Novo Cadastro</button></div><div class="panel-content"><details class="filters-details"><summary>Buscar e filtrar</summary><form id="filters"><label for="search">Nome ou descrição</label><input id="search" type="search" placeholder="Buscar no inventário"><div class="form-grid"><div><label for="kind-filter">Tipo</label><select id="kind-filter"><option value="">Todos</option><option value="trilha">Trilha</option><option value="nascente">Nascente</option></select></div><div><label for="status-filter">Conservação</label><select id="status-filter"><option value="">Todas</option><option value="a_verificar">A verificar</option><option value="conservado">Conservado</option><option value="atencao">Atenção</option></select></div></div><div class="filter-actions"><button type="submit">Filtrar</button><a id="export" href="/api/geojson" class="text-button">Exportar GeoJSON ↗</a></div></form></details><p id="empty" hidden>Nenhum registro encontrado. Cadastre um item ou ajuste os filtros.</p><div id="records"></div></div><div class="panel-footer list-footer"><span id="total">Total: 0 itens</span><span id="filtered-summary"></span></div></section>
<section id="detail-panel" class="side-panel" hidden><div class="panel-heading"><button class="back" id="detail-back">← Voltar</button></div><div id="detail-content" class="panel-content"></div><div id="detail-actions" class="panel-footer"></div></section>
<section id="editor-panel" class="side-panel" hidden><div class="panel-heading editor-heading"><button type="button" id="editor-back" class="back">← Voltar</button><h1 id="editor-title">Novo Cadastro</h1></div><form id="feature-form" class="editor-form"><div class="panel-content">
<label for="name">Nome</label><input id="name" required minlength="3" maxlength="120"><label for="kind">Categoria</label><select id="kind"><option value="trilha">Trilha</option><option value="nascente">Nascente</option></select><label for="description">Descrição</label><textarea id="description" rows="3" maxlength="4000"></textarea><label for="photo-url">Link das fotos</label><input id="photo-url" type="url" maxlength="2048" placeholder="https://drive.google.com/drive/folders/...">
<div class="geo-section"><h2>Georreferenciamento</h2><div class="tabs" role="tablist" aria-label="Forma de georreferenciamento"><button type="button" id="file-tab" role="tab" aria-selected="true" aria-controls="file-panel">GPX/KML</button><button type="button" id="coords-tab" role="tab" aria-selected="false" aria-controls="coords-panel" tabindex="-1">Coordenadas</button></div><div id="file-panel" role="tabpanel" aria-labelledby="file-tab"><label class="file-drop" for="geometry-file"><span id="file-label">Clique para carregar arquivo .gpx ou .kml</span><small>Tamanho máximo: 15 MB</small><input id="geometry-file" type="file" accept=".gpx,.kml"></label><p id="import-status" role="status"></p></div><div id="coords-panel" role="tabpanel" aria-labelledby="coords-tab" hidden><label for="coordinates">Longitude, latitude</label><textarea id="coordinates" rows="4" aria-describedby="coord-help" placeholder="-46.3000, -23.7700"></textarea><p id="coord-help">Nascente: um par. Trilha: um par por linha; separe segmentos com uma linha em branco. WGS84, graus decimais.</p></div></div>
<details id="metadata"><summary>Informações complementares</summary><label for="category">Classificação de uso (opcional)</label><input id="category" maxlength="120" placeholder="Ex.: Rota de Pesquisa"><label for="status">Situação de conservação</label><select id="status"><option value="a_verificar">A verificar</option><option value="conservado">Conservado</option><option value="atencao">Atenção</option></select><label for="source">Origem dos dados / responsável</label><input id="source" required maxlength="250"><label for="observed-on">Data da observação</label><input id="observed-on" type="date" required></details><p id="form-error" role="alert"></p>
</div><div class="panel-footer editor-footer"><button type="submit" id="save">Salvar</button></div></form></section>
</aside><section class="map-area" aria-label="Mapa do inventário"><div id="map"></div><p id="map-note" hidden>Mapa indisponível. Os dados e coordenadas podem ser consultados na lista.</p><div class="map-legend"><span><i class="trail-key"></i>Trilha</span><span><i class="spring-key"></i>Nascente</span></div></section></div></section>
<p id="message" class="toast" role="status" aria-live="polite" hidden></p></main>
<dialog id="delete-dialog" aria-labelledby="delete-title" aria-describedby="delete-description"><div class="delete-body"><span class="warning-icon" aria-hidden="true">⚠</span><div><h2 id="delete-title">Confirmar exclusão</h2><p id="delete-description"></p><p id="delete-error" role="alert"></p></div></div><div class="dialog-footer"><button id="cancel-delete" class="secondary">Cancelar</button><button id="confirm-delete" class="danger">Sim, excluir</button></div></dialog>
<dialog id="history" aria-labelledby="history-title"><div class="history-heading"><h2 id="history-title">Histórico do registro</h2><button id="close-history" class="secondary">Fechar</button></div><div id="history-items"></div></dialog></body></html>'''

CSS = r''':root{--green:#194333;--ink:#111b2e;--muted:#62758e;--line:#e0e6ee;--field:#f7f8fa;--sidebar:500px}*{box-sizing:border-box}body{margin:0;background:white;color:var(--ink);font:14px/1.55 Inter,Arial,sans-serif}button,input,textarea,select{font:inherit}button,.button{border:1px solid var(--green);background:var(--green);color:white;border-radius:6px;padding:13px 18px;cursor:pointer;line-height:1.5}button:hover{filter:brightness(.95)}button:disabled{opacity:.55;cursor:wait}a{color:#125ee9}input,textarea,select{width:100%;border:1px solid #cbd5e1;background:var(--field);border-radius:5px;padding:9px 12px;color:#414750}input::placeholder,textarea::placeholder{color:#929eaf}textarea{resize:vertical;min-height:60px}label{display:block;margin:17px 0 5px;font-size:12px;letter-spacing:.045em;text-transform:uppercase;color:#34445d;font-weight:600}h1,h2,h3,p{margin-top:0}p{line-height:1.65}h1{font-size:24px;line-height:1.35}h2{font-size:19px}h3{font-size:16px}summary{cursor:pointer;color:#526781}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid #b27a12;outline-offset:3px}[hidden]{display:none!important}.skip{position:absolute;top:-80px;left:10px;background:white;padding:10px;z-index:2000}.skip:focus{top:10px}
.login-layout{display:grid;grid-template-columns:58.3% 41.7%;min-height:100dvh}.login-brand{background:var(--green);color:white;display:flex;align-items:center;justify-content:center;padding:55px}.login-brand>div{width:100%;max-width:450px}.login-brand h1{font-size:32px;letter-spacing:-1px;line-height:1.45;margin-bottom:20px}.login-brand p{color:#d2e8dc;font-size:16px;line-height:1.65;margin:0}.login-form-panel{display:flex;align-items:center;justify-content:center;padding:40px}.login-form-panel form{width:100%;max-width:384px}.login-form-panel h2{text-align:center;font-size:25px;margin-bottom:30px}.login-form-panel label{text-transform:none;letter-spacing:0;font-weight:400;font-size:14px;margin-top:20px}.login-form-panel input{padding:10px 14px;height:43px}.login-form-panel button{width:100%;margin-top:26px;padding:10px}#login-error:empty{display:none}#login-error,#form-error,#delete-error{color:#b42318;margin:10px 0;font-size:13px}
.app-header{height:60px;border-bottom:1px solid var(--line);display:grid;grid-template-columns:1fr auto 1fr;align-items:center;padding:0 24px;gap:20px}.brand{display:flex;align-items:center;gap:10px;font-weight:700;text-decoration:none;color:var(--ink);font-size:16px}.brand-icon{width:33px;height:33px;background:var(--green);color:white;border-radius:9px;display:grid;place-items:center}.brand-icon svg{width:25px;height:25px}.app-title{font-weight:600}#identity{justify-self:end;display:flex;align-items:center;gap:10px;font-size:12px;color:var(--muted)}#identity button{padding:5px 10px;background:white;color:var(--green);border-color:var(--line)}.inventory-layout{height:calc(100dvh - 60px);display:grid;grid-template-columns:var(--sidebar) minmax(0,1fr)}#sidebar{min-height:0;border-right:1px solid var(--line)}.side-panel{height:100%;display:flex;flex-direction:column}.panel-heading{height:99px;flex-shrink:0;border-bottom:1px solid #eef1f5;display:flex;align-items:center;justify-content:space-between;padding:24px;gap:16px}.panel-heading h1{font-size:16px;font-weight:600;color:#34445d;margin:0}.panel-heading button:not(.back){min-width:150px}.panel-content{padding:16px 18px;overflow-y:auto;flex:1;min-height:0}.panel-footer{min-height:82px;background:#f8fafc;border-top:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;gap:15px;padding:16px 24px;flex-shrink:0}.list-footer{min-height:56px;font-size:13px;color:#34445d}#filtered-summary{color:var(--muted);font-size:11px}.filters-details{margin-bottom:14px;font-size:12px}.filters-details>summary{padding:3px 7px}.filters-details[open]{padding:8px;border:1px solid var(--line);border-radius:6px}.filter-actions{display:flex;align-items:center;gap:15px;margin:14px 0 4px}.filter-actions button{padding:7px 14px}.text-button{border:0;background:transparent;color:var(--green);padding:0;text-decoration:none;font-size:13px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.record{width:100%;text-align:left;background:white;border:1px solid var(--line);border-radius:5px;padding:16px;margin-bottom:12px;display:block;color:var(--ink)}.record:hover,.record.selected{background:#f7f9fb;border-left:4px solid var(--green);padding-left:13px}.record-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:6px}.tag{font-size:11px;letter-spacing:.05em;font-weight:700;background:#ecfcf4;color:#215a43;padding:2px 8px;border-radius:2px;text-transform:uppercase}.tag.nascente{background:#eff6ff;color:#1757ed}.active-label{font-size:11px;color:#7e90a5}.record h3{margin:0 0 5px;font-weight:600}.record p{font-size:12px;color:var(--muted);margin:0;overflow:hidden;text-overflow:ellipsis;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}.back{border:0;background:white;color:var(--green);padding:0;font-size:18px;font-weight:600;white-space:nowrap}.editor-heading{justify-content:start;height:80px;gap:26px}.editor-heading h1{border-left:1px solid #cbd5e1;padding-left:16px;font-size:24px;color:var(--ink);font-weight:700}.editor-form{flex:1;min-height:0;display:flex;flex-direction:column}.editor-form>.panel-content{padding:8px 24px 24px}.editor-footer{justify-content:end}.editor-footer button{min-width:150px}.geo-section{border-top:1px solid #eef1f5;margin-top:16px;padding-top:8px}.geo-section h2{font-size:12px;letter-spacing:.045em;text-transform:uppercase;color:#34445d;margin:0 0 7px}.tabs{display:flex;border:1px solid var(--line);background:#f0f3f8;border-radius:5px;padding:4px;gap:5px;margin-bottom:8px}.tabs button{flex:1;border:1px solid transparent;background:transparent;color:#34445d;font-size:12px;padding:8px}.tabs button[aria-selected=true]{background:white;border-color:#e3e8ef;color:var(--green);font-weight:600}.file-drop{position:relative;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center;min-height:66px;padding:12px;border:1px dashed #c7d2e0;border-radius:5px;background:var(--field);font-size:12px;font-weight:400;letter-spacing:0;text-transform:none;margin:0;overflow-wrap:anywhere;cursor:pointer}.file-drop small{color:#8799af;font-size:11px}.file-drop input{position:absolute;inset:0;opacity:0;cursor:pointer;width:100%;height:100%}.file-drop:focus-within{outline:3px solid #b27a12;outline-offset:3px}#import-status,#coord-help{font-size:11px;color:var(--muted);margin:6px 0}#metadata{margin-top:24px;font-size:12px}#detail-panel .panel-content{padding:24px}#detail-panel h1{font-size:24px;margin:12px 0 22px}.detail-row{border-bottom:1px solid #eef1f5;padding:0 0 14px;margin:0 0 18px}.detail-label{text-transform:uppercase;color:var(--muted);font-size:12px;font-weight:600;letter-spacing:.035em;margin-bottom:4px}.detail-row p{margin:0;color:#34445d;white-space:pre-wrap}.photo-link{text-decoration:none}.detail-meta{font-size:12px;color:var(--muted)}#detail-actions button{flex:1}.danger{background:#e92127;border-color:#e92127;color:white}.danger-outline{background:white;color:#e92127;border-color:#e92127}.secondary{background:#f8fafc;border-color:var(--line);color:#34445d}
.map-area{position:relative;min-width:0;min-height:0;background:#e2e9e0}#map{height:100%;width:100%;z-index:0}.map-legend{position:absolute;bottom:27px;left:16px;display:flex;gap:16px;align-items:center;border-radius:5px;background:#ffffffed;padding:8px 12px;font-size:11px;box-shadow:0 2px 8px #0001;z-index:450}.map-legend span{display:flex;align-items:center;gap:6px}.trail-key{width:18px;height:3px;background:var(--green)}.spring-key{width:9px;height:9px;border-radius:50%;background:#176ed8}#map-note{position:absolute;top:20px;left:20px;right:20px;background:white;padding:14px;border-radius:5px;z-index:450;font-size:13px}.toast{position:fixed;bottom:20px;left:50%;transform:translateX(-50%);margin:0;background:var(--green);color:white;padding:12px 18px;border-radius:7px;box-shadow:0 5px 25px #0002;z-index:1500;max-width:calc(100% - 30px);font-size:13px}.leaflet-container{font-family:inherit}dialog{padding:0;border:1px solid var(--line);border-radius:14px;max-width:520px;width:calc(100% - 32px);max-height:85dvh;color:var(--ink);box-shadow:0 18px 45px #0003}dialog::backdrop{background:#15223233}.delete-body{padding:28px 24px 22px;display:flex;gap:16px}.delete-body h2{margin-bottom:5px;font-size:19px}.delete-body p{margin:0;color:#526078}.warning-icon{width:40px;height:40px;flex-shrink:0;border-radius:50%;background:#fff3f3;color:#e92127;display:grid;place-items:center;font-size:24px}.dialog-footer{display:flex;justify-content:end;gap:12px;padding:16px 24px;background:#f8fafc;border-top:1px solid #edf1f5}.dialog-footer button{padding:9px 16px}.history-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:20px}.history-heading h2{margin:0}#history-items{padding:0 20px 20px}.history-entry{border-top:1px solid var(--line);padding:12px 0}.history-entry p{font-size:12px;color:var(--muted);margin:4px 0}
@media(min-width:1600px){:root{--sidebar:520px}}@media(max-width:1100px){:root{--sidebar:390px}.login-brand{padding:35px}.login-brand h1{font-size:28px}.login-form-panel{padding:30px}.editor-heading{gap:16px}.editor-heading h1{font-size:21px}}@media(max-width:700px){.login-layout{grid-template-columns:1fr}.login-brand{padding:42px 25px}.login-brand h1{font-size:26px}.login-form-panel{padding:40px 25px}.app-header{grid-template-columns:1fr auto;padding:0 14px;height:64px}.app-title{display:none}#identity span{display:none}.inventory-layout{height:auto;min-height:calc(100dvh - 64px);grid-template-columns:1fr}#sidebar{height:65dvh;min-height:420px;border-right:0}.map-area{height:45dvh;min-height:280px;border-top:1px solid var(--line)}.panel-heading{height:80px;padding:18px}.panel-content{padding:14px}.editor-heading h1{font-size:21px}.editor-form>.panel-content{padding:8px 18px 22px}.panel-footer{padding:12px 18px}.map-legend{bottom:25px}}'''

JS = r''' 'use strict';
const $=id=>document.getElementById(id);
const labels={trilha:'Trilha',nascente:'Nascente',a_verificar:'A verificar',conservado:'Conservado',atencao:'Atenção'};
let user,csrf,items=[],selected=null,editing=null,map,layer,preview,geometry=null,geometryFile='',mode='file',uploading=false,uploadGeneration=0,toastTimer;
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function message(text){$('message').textContent=text;$('message').hidden=!text;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('message').hidden=true,7000);}
async function api(path,options={}){const multipart=options.body instanceof FormData;const response=await fetch(path,{...options,headers:{...(multipart?{}:{'Content-Type':'application/json'}),'X-CSRF-Token':csrf||'',...options.headers}});if(response.status===204)return null;let data;try{data=await response.json();}catch{throw new Error('Resposta inválida do servidor. Confira se ele está atualizado.');}if(!response.ok){if(response.status===401)showLogin();throw new Error(data.error||'Falha na operação.');}return data;}
function showLogin(){user=null;csrf=null;uploadGeneration++;$('workspace').hidden=true;$('login-panel').hidden=false;$('identity').replaceChildren();for(const id of ['history','delete-dialog'])if($(id).open)$(id).close();}
function localDate(){const now=new Date();return `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;}
async function enter(data){user=data;csrf=data.csrf;$('workspace').hidden=false;$('login-panel').hidden=true;$('password').value='';$('identity').replaceChildren(el('span',data.username));const logout=el('button','Sair');logout.onclick=async()=>{try{await api('/api/logout',{method:'POST'});showLogin();}catch(e){message(e.message);}};$('identity').append(logout);$('new-feature').hidden=user.role==='leitor';setPanel('list');await refresh();}
function setPanel(name){for(const key of ['list','detail','editor'])$(key+'-panel').hidden=key!==name;if(preview&&name!=='editor')preview.clearLayers();if(map)requestAnimationFrame(()=>map.invalidateSize());}
function query(){return new URLSearchParams({q:$('search').value.trim(),kind:$('kind-filter').value,status:$('status-filter').value}).toString();}
async function refresh(){const data=await api('/api/features?'+query());items=data.items;$('export').href='/api/geojson?'+query();render();}
function initMap(){if(map)return;if(!window.L){$('map-note').hidden=false;return;}map=L.map('map',{zoomControl:false}).setView([-23.77,-46.3],13);L.control.zoom({position:'topright'}).addTo(map);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).on('tileerror',()=>$('map-note').hidden=false).addTo(map);layer=L.geoJSON(null,{style:f=>({color:'#194333',weight:f.properties.id===selected?.id?6:4}),pointToLayer:(f,ll)=>L.circleMarker(ll,{radius:8,color:'#176ed8',fillOpacity:.85}),onEachFeature:(f,l)=>{const content=el('div');content.append(el('strong',f.properties.name),el('p',labels[f.properties.kind]));const button=el('button','Ver detalhes');button.onclick=()=>showDetail(items.find(x=>x.id===f.properties.id));content.append(button);l.bindPopup(content);l.on('click',()=>showDetail(items.find(x=>x.id===f.properties.id),false));}}).addTo(map);preview=L.geoJSON(null,{style:{color:'#d88716',weight:5,dashArray:'6 5'},pointToLayer:(f,ll)=>L.circleMarker(ll,{color:'#d88716',radius:9})}).addTo(map);}
function render(){const filtered=$('search').value||$('kind-filter').value||$('status-filter').value;$('total').textContent=`Total: ${items.length} ${items.length===1?'item':'itens'}`;$('filtered-summary').textContent=filtered?'Resultados filtrados':'';$('records').replaceChildren();$('empty').hidden=items.length>0;for(const item of items){const card=el('button',undefined,'record'+(item.id===selected?.id?' selected':''));card.type='button';const top=el('div',undefined,'record-top');top.append(el('span',labels[item.kind],'tag '+item.kind),el('span','Ativo','active-label'));card.append(top,el('h3',item.name),el('p',item.description||'Sem descrição.'));card.onclick=()=>showDetail(item);$('records').append(card);}initMap();if(layer){layer.clearLayers();layer.addData({type:'FeatureCollection',features:items.map(x=>({type:'Feature',geometry:x.geometry,properties:x}))});map.invalidateSize();if(items.length)map.fitBounds(layer.getBounds(),{padding:[35,35],maxZoom:16});}}
function focusGeometry(item){if(!map||!item)return;const bounds=L.geoJSON(item.geometry).getBounds();if(bounds.isValid())map.fitBounds(bounds,{padding:[40,40],maxZoom:16});}
function detailRow(label,text){const row=el('div',undefined,'detail-row');row.append(el('div',label,'detail-label'),el('p',text));return row;}
function showDetail(item,focus=true){if(!item)return;selected=item;setPanel('detail');const content=$('detail-content');content.replaceChildren(el('span','Item cadastrado','tag'),el('h1',item.name));content.append(detailRow('Categoria',item.category||labels[item.kind]),detailRow('Descrição',item.description||'Sem descrição.'),detailRow('Extensão / geometria',item.kind==='trilha'?`${Math.round(item.length_m).toLocaleString('pt-BR')} metros lineares (estimativa geodésica)${item.geometry_file?' · '+item.geometry_file:''}`:'Ponto georreferenciado (WGS84)'));
const photos=el('div',undefined,'detail-row');photos.append(el('div','Registro fotográfico','detail-label'));if(item.photo_url){const link=el('a',new URL(item.photo_url).hostname==='drive.google.com'?'Ver fotos no Drive ↗':'Ver fotos ↗','photo-link');link.href=item.photo_url;link.target='_blank';link.rel='noopener noreferrer';photos.append(link);}else photos.append(el('p','Nenhum link de fotos informado.'));content.append(photos);const meta=el('details',undefined,'detail-meta');meta.append(el('summary','Dados do levantamento'),detailRow('Tipo',labels[item.kind]),detailRow('Conservação',labels[item.status]),detailRow('Origem',item.source),detailRow('Data',item.observed_on),el('pre',JSON.stringify(item.geometry,null,2)));const history=el('button','Ver histórico','text-button');history.onclick=()=>showHistory(item);meta.append(history);content.append(meta);const actions=$('detail-actions');actions.replaceChildren();if(user.role==='gestor'){const remove=el('button','Excluir','danger-outline');remove.onclick=()=>openDelete(item);actions.append(remove);}if(user.role!=='leitor'){const edit=el('button','Editar');edit.onclick=()=>openEditor(item);actions.append(edit);}else actions.append(el('span','Acesso de consulta','detail-meta'));if(layer)layer.setStyle(f=>({weight:f.properties.id===item.id?6:4}));if(focus)focusGeometry(item);}
function geometryText(value){if(!value)return '';if(value.type==='Point')return value.coordinates.join(', ');const segments=value.type==='LineString'?[value.coordinates]:value.coordinates;return segments.map(points=>points.map(p=>p.join(', ')).join('\n')).join('\n\n');}
function chooseMode(next){mode=next;for(const [key,id]of[['file','file'],['coords','coords']]){const active=key===next;$(id+'-tab').setAttribute('aria-selected',String(active));$(id+'-tab').tabIndex=active?0:-1;$(id+'-panel').hidden=!active;}if(next==='coords')updateCoordinatePreview();else showPreview(geometry);}
function openEditor(item){editing=item||null;uploadGeneration++;uploading=false;$('save').disabled=false;$('feature-form').reset();$('metadata').open=false;$('form-error').textContent='';$('import-status').textContent='';$('editor-title').textContent=item?'Editar Cadastro':'Novo Cadastro';geometry=item?.geometry||null;geometryFile=item?.geometry_file||'';if(item){for(const key of ['name','kind','description','status','source','category'])$(key).value=item[key]||'';$('photo-url').value=item.photo_url||'';$('observed-on').value=item.observed_on;}else{$('source').value=user.username;$('observed-on').value=localDate();}$('coordinates').value=geometryText(geometry);$('file-label').textContent=geometryFile||'Clique para carregar arquivo .gpx ou .kml';setPanel('editor');chooseMode(item&&!geometryFile?'coords':'file');showPreview(geometry);$('name').focus();}
function manualGeometry(){const text=$('coordinates').value.trim();if(!text)throw new Error('Informe as coordenadas ou importe um arquivo.');const segments=text.split(/\n\s*\n/).map(segment=>segment.split(/\n/).filter(x=>x.trim()).map(line=>{const parts=line.split(',').map(x=>x.trim());if(parts.length!==2||parts.some(x=>!x))throw new Error('Use longitude, latitude em cada linha.');const numbers=parts.map(Number);if(numbers.some(x=>!Number.isFinite(x))||Math.abs(numbers[0])>180||Math.abs(numbers[1])>90)throw new Error('Coordenadas inválidas.');return numbers;}));if($('kind').value==='nascente'){if(segments.length!==1||segments[0].length!==1)throw new Error('Informe um único ponto para a nascente.');return {type:'Point',coordinates:segments[0][0]};}if(segments.some(points=>points.length<2))throw new Error('Cada segmento deve ter pelo menos dois pontos.');return {type:segments.length===1?'LineString':'MultiLineString',coordinates:segments.length===1?segments[0]:segments};}
function showPreview(value){if(!preview)return;preview.clearLayers();if(value){preview.addData(value);const bounds=preview.getBounds();if(bounds.isValid())map.fitBounds(bounds,{padding:[40,40],maxZoom:16});}}
function updateCoordinatePreview(){try{showPreview(manualGeometry());}catch{showPreview(null);}}
async function importFile(){const file=$('geometry-file').files[0];if(!file)return;const token=++uploadGeneration;geometry=null;geometryFile='';showPreview(null);$('coordinates').value='';if(file.size>15*1024*1024){$('form-error').textContent='O arquivo deve ter no máximo 15 MB.';$('geometry-file').value='';return;}uploading=true;$('save').disabled=true;$('import-status').textContent='Validando o arquivo…';$('form-error').textContent='';const form=new FormData();form.append('file',file);form.append('kind',$('kind').value);try{const result=await api('/api/import-geometry',{method:'POST',body:form});if(token!==uploadGeneration)return;geometry=result.geometry;geometryFile=result.geometry_file;$('coordinates').value=geometryText(geometry);$('file-label').textContent=file.name;$('import-status').textContent='Geometria validada. Salve para cadastrar o registro.';showPreview(geometry);}catch(e){if(token===uploadGeneration){$('form-error').textContent=e.message;$('import-status').textContent='';$('file-label').textContent='Clique para carregar arquivo .gpx ou .kml';}}finally{if(token===uploadGeneration){uploading=false;$('save').disabled=false;}}}
function openDelete(item){selected=item;$('delete-description').replaceChildren(document.createTextNode('Esta ação não poderá ser desfeita. Todos os dados, histórico e pontos georreferenciados de '),el('strong',item.name),document.createTextNode(' serão removidos permanentemente.'));$('delete-error').textContent='';$('delete-dialog').showModal();$('cancel-delete').focus();}
async function showHistory(item){try{const data=await api(`/api/features/${item.id}/history`);$('history-title').textContent=`Histórico: ${item.name}`;$('history-items').replaceChildren();for(const entry of data.items){const section=el('article',undefined,'history-entry');section.append(el('strong',`${entry.action} · ${entry.username}`),el('p',new Date(entry.created_at).toLocaleString('pt-BR')));const details=el('details');details.append(el('summary','Ver esta versão'),el('pre',JSON.stringify(JSON.parse(entry.snapshot),null,2)));section.append(details);$('history-items').append(section);}$('history').showModal();}catch(e){message(e.message);}}
$('login-form').onsubmit=async event=>{event.preventDefault();$('login-button').disabled=true;$('login-error').textContent='';try{await enter(await api('/api/login',{method:'POST',body:JSON.stringify({username:$('username').value,password:$('password').value})}));}catch(e){$('login-error').textContent=e.message;}finally{$('login-button').disabled=false;}};
$('filters').onsubmit=async event=>{event.preventDefault();try{selected=null;await refresh();}catch(e){message(e.message);}};
$('new-feature').onclick=()=>openEditor();$('detail-back').onclick=()=>{selected=null;setPanel('list');};$('editor-back').onclick=()=>{uploadGeneration++;if(editing)showDetail(editing);else setPanel('list');};
$('file-tab').onclick=()=>chooseMode('file');$('coords-tab').onclick=()=>chooseMode('coords');for(const id of ['file-tab','coords-tab'])$(id).onkeydown=event=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const target=event.key==='Home'?'file':event.key==='End'?'coords':mode==='file'?'coords':'file';chooseMode(target);$(target+'-tab').focus();}};
$('geometry-file').onchange=importFile;$('coordinates').oninput=updateCoordinatePreview;$('kind').onchange=()=>{uploadGeneration++;uploading=false;$('save').disabled=false;geometry=null;geometryFile='';$('geometry-file').value='';$('file-label').textContent='Clique para carregar arquivo .gpx ou .kml';$('import-status').textContent='';showPreview(null);if(mode==='coords')updateCoordinatePreview();};
$('feature-form').addEventListener('invalid',event=>{if($('metadata').contains(event.target))$('metadata').open=true;},true);
$('feature-form').onsubmit=async event=>{event.preventDefault();if(uploading)return;$('save').disabled=true;$('form-error').textContent='';try{const geo=mode==='coords'?manualGeometry():geometry;if(!geo)throw new Error('Importe um arquivo GPX/KML ou informe as coordenadas.');const body={geometry:geo,geometry_file:mode==='file'?geometryFile:'',photo_url:$('photo-url').value,observed_on:$('observed-on').value};for(const key of ['name','kind','description','status','source','category'])body[key]=$(key).value;if(editing)body.version=editing.version;const saved=await api('/api/features'+(editing?'/'+editing.id:''),{method:editing?'PUT':'POST',body:JSON.stringify(body)});await refresh();showDetail(items.find(x=>x.id===saved.id));message('Cadastro salvo.');}catch(e){$('form-error').textContent=e.message;}finally{$('save').disabled=false;}};
$('cancel-delete').onclick=()=>$('delete-dialog').close();$('confirm-delete').onclick=async()=>{if(!selected)return;$('confirm-delete').disabled=true;try{await api(`/api/features/${selected.id}`,{method:'DELETE',body:JSON.stringify({version:selected.version})});$('delete-dialog').close();selected=null;setPanel('list');await refresh();message('Cadastro excluído.');}catch(e){$('delete-error').textContent=e.message;}finally{$('confirm-delete').disabled=false;}};$('close-history').onclick=()=>$('history').close();
api('/api/session').then(enter).catch(error=>{showLogin();if(!error.message.includes('Entre para acessar'))$('login-error').textContent=error.message;});
'''

# Ajustes finos após comparação das capturas com o Figma.
import re
filters = re.search(r'<details class="filters-details">.*?</details>', HTML, re.S).group(0)
HTML = HTML.replace(filters, '').replace('<span id="filtered-summary">', filters+'<span id="filtered-summary">')
HTML = HTML.replace('rows="3" maxlength="4000"', 'rows="2" maxlength="4000"')
CSS += r'''
.login-brand h1{white-space:nowrap}.editor-form input,.editor-form select{height:38px;padding:7px 12px}.editor-form #description{height:58px;min-height:58px;line-height:1.4;padding:8px 12px}#detail-panel .panel-heading{height:80px}.list-footer{position:relative}.filters-details{margin:0}.filters-details>summary{white-space:nowrap}.filters-details[open]{position:absolute;bottom:10px;left:18px;right:18px;background:white;z-index:500;box-shadow:0 5px 20px #0002}.record{min-height:102px}@media(max-width:1100px){.login-brand h1{white-space:normal}}'''
JS = JS.replace("color:'#194333',weight:f.properties.id===selected?.id?6:4", "color:f.properties.kind==='nascente'?'#176ed8':'#194333',weight:f.properties.id===selected?.id?6:4")
JS = JS.replace("({weight:f.properties.id===item.id?6:4})", "({color:f.properties.kind==='nascente'?'#176ed8':'#194333',weight:f.properties.id===item.id?6:4})")

if __name__ == '__main__':
    root = Path(__file__).resolve().parents[1]
    for relative, content in [('inventario/templates/index.html',HTML),('inventario/static/style.css',CSS),('inventario/static/app.js',JS)]:
        (root/relative).write_text(content,encoding='utf-8')
    print('Interface atualizada conforme referências do Figma.')
